import{_ as t,o as a,c as s,a5 as d}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"Sport Client — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/sport-client.md","filePath":"software/sdk/cpp/sport-client.md","lastUpdated":1787021357000}'),o={name:"software/sdk/cpp/sport-client.md"};function i(n,e,l,r,c,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="sport-client-—-c-example" tabindex="-1">Sport Client — C++ Example <a class="header-anchor" href="#sport-client-—-c-example" aria-label="Permalink to &quot;Sport Client — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_sport_client.cpp</code></p><p>An interactive terminal application that sends <strong>SportClient</strong> commands to the robot one at a time.<br> Type a command name (or its numeric ID) and the application executes it in a 50 Hz loop until you type a different command.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The program has a single loop that:</p><ol><li>Reads a line of input from <code>stdin</code> (<code>list</code>, a command name, or a command ID).</li><li>Updates the current <code>test_option</code>.</li><li>Calls the matching <code>SportClient</code> method on every 20 ms tick.</li></ol><p>There is <strong>no separate control thread</strong> — the terminal read blocks until the user presses Enter, making this a simple sequential test harness.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>Robot stack running (simulation or hardware) and reachable on the same network.</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_sport_client</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e.g.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><h2 id="available-commands" tabindex="-1">Available commands <a class="header-anchor" href="#available-commands" aria-label="Permalink to &quot;Available commands&quot;">​</a></h2><p>Type <code>list</code> at the prompt to print all commands, or use the numeric ID directly.</p><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>SportClient method called</th></tr></thead><tbody><tr><td>0</td><td><code>damp</code></td><td><code>Damp()</code> — high-damping e-stop</td></tr><tr><td>1</td><td><code>balance_stand</code></td><td><code>BalanceStand()</code> — balanced standing</td></tr><tr><td>2</td><td><code>stop_move</code></td><td><code>StopMove()</code> — stop in place</td></tr><tr><td>3</td><td><code>stand_down</code></td><td><code>StandDown()</code> — go prone</td></tr><tr><td>4</td><td><code>recovery_stand</code></td><td><code>RecoveryStand()</code> — stand up from fall</td></tr><tr><td>5</td><td><code>move</code></td><td><code>Move(0.0, 0.0, 0.5)</code> — rotate in place</td></tr><tr><td>6</td><td><code>switch_gait</code></td><td><code>SwitchGait(0)</code> — switch to default gait</td></tr><tr><td>7</td><td><code>speed_level</code></td><td><code>SpeedLevel(1)</code> — set speed level</td></tr><tr><td>8</td><td><code>get_state</code></td><td><code>GetState()</code> — print FSM / speed / process state</td></tr><tr><td>9</td><td><code>recovery_switch</code></td><td><code>SetAutoRecovery(0)</code> — disable auto-recovery</td></tr><tr><td>10</td><td><code>body_height</code></td><td><code>BodyHeight(0.3f)</code> — set body height +0.3 m</td></tr><tr><td>11</td><td><code>stand_up</code></td><td><code>StandUp()</code> — lock joints in standing position</td></tr><tr><td>12</td><td><code>enter_leftside_gait</code></td><td><code>LeftSideGait(1)</code></td></tr><tr><td>13</td><td><code>exit_leftside_gait</code></td><td><code>LeftSideGait(0)</code></td></tr><tr><td>14</td><td><code>enter_handstand</code></td><td><code>HandStand(1)</code></td></tr><tr><td>15</td><td><code>exit_handstand</code></td><td><code>HandStand(0)</code></td></tr><tr><td>16</td><td><code>front_flip</code></td><td><code>FrontFlip()</code> ⚠️</td></tr><tr><td>17</td><td><code>back_flip</code></td><td><code>BackFlip()</code> ⚠️</td></tr><tr><td>18</td><td><code>pose</code></td><td><code>BodyPosition(0.2, 0.2, -0.2, 0.2)</code></td></tr><tr><td>19</td><td><code>euler</code></td><td><code>Euler(0.2, 0.3, 0.3)</code></td></tr></tbody></table><blockquote><p><strong>⚠️ Caution</strong> — <code>front_flip</code> and <code>back_flip</code> require a clear open area.<br> Run these only when the robot has sufficient space on all sides.</p></blockquote><h2 id="usage-example" tabindex="-1">Usage example <a class="header-anchor" href="#usage-example" aria-label="Permalink to &quot;Usage example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ./bin/rbq_sport_client eth0</span></span>
<span class="line"><span>Input &quot;list &quot; to list all test option ...</span></span>
<span class="line"><span>balance_stand</span></span>
<span class="line"><span>Test: balance_stand, test_id: 1</span></span>
<span class="line"><span>Request successed: balance_stand, code: 0</span></span>
<span class="line"><span>Request successed: balance_stand, code: 0</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>move</span></span>
<span class="line"><span>Test: move, test_id: 5</span></span>
<span class="line"><span>Request successed: move, code: 0</span></span>
<span class="line"><span>...</span></span></code></pre></div><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong>SetNoReply(true)</strong>: The <code>SportClient</code> is initialised with <code>SetNoReply(true)</code>. This fires each request as a DDS publish without waiting for an RPC response — suitable for high-frequency control over WiFi where round-trip latency is unpredictable.</li><li><strong>50 Hz tick</strong>: <code>std::this_thread::sleep_until</code> enforces the 20 ms loop period.</li><li><strong>Error counting</strong>: A <code>res_count</code> variable accumulates consecutive failures and prints the count alongside error codes.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/cpp/sport-client-joy.html">Sport Client (Joystick)</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a></li></ul>`,25)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
